import sys

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    T = int(data[0])
    index = 1
    results = []

    for _ in range(T):
        S = data[index]
        index += 1
        if '1' in S:
            results.append("WIN")
        else:
            results.append("LOSE")

    for result in results:
        print(result)

if __name__ == "__main__":
    main()
